//! The corpus as typed tables, generated by `build.rs` (no text: see `names` for that).

use crate::ids::{PlanetIx, SystemIx};

/// Anomaly and tile flags of a system record.
pub struct SystemFlags;

impl SystemFlags {
    pub const NEBULA: u8 = 1;
    pub const SUPERNOVA: u8 = 1 << 1;
    pub const ASTEROID_FIELD: u8 = 1 << 2;
    pub const GRAVITY_RIFT: u8 = 1 << 3;
    pub const HYPERLANE: u8 = 1 << 4;
    pub const SCAR: u8 = 1 << 5;
    /// The Wormhole Nexus faces (`82*`), whose alpha and beta Nexus Sovereignty switches off.
    pub const NEXUS: u8 = 1 << 6;
}

/// One system record.
#[derive(Debug)]
pub struct SystemData {
    pub flags: u8,
    /// Printed wormhole kinds, one bit per kind (`WH_*`).
    pub wormholes: u8,
    /// The record's source tag as one bit (see `Scope`).
    pub source: u32,
    /// The printed lanes of a hyperlane tile after its turn, as edge pairs; `None` for every other
    /// tile (and for a hyperlane id the lane table does not know).
    pub lanes: Option<&'static [(u8, u8)]>,
    pub planets: &'static [PlanetIx],
}

impl SystemData {
    #[must_use]
    pub const fn has(&self, flag: u8) -> bool {
        self.flags & flag != 0
    }
}

/// One planet record (the economy and location; the movement slice does not read it).
#[derive(Debug)]
pub struct PlanetData {
    pub system: Option<SystemIx>,
    pub resources: i64,
    pub influence: i64,
    pub source: u32,
    pub space_station: bool,
}

/// One unit type record.
#[derive(Debug)]
pub struct UnitData {
    pub is_ship: bool,
    pub moves_as_ship: bool,
    pub source: u32,
}

include!(concat!(env!("OUT_DIR"), "/tables.rs"));

/// A set of sources (expansions) as a bit mask over the record source bits.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Scope(pub u32);

impl Scope {
    #[must_use]
    pub const fn system(self, system: SystemIx) -> Option<&'static SystemData> {
        let data = &SYSTEMS[system.index()];
        if data.source & self.0 != 0 {
            Some(data)
        } else {
            None
        }
    }
}

/// Bits of the alpha and beta kinds (Wormhole Reconstruction, Lost Star Chart, Nexus Sovereignty).
pub const WH_ALPHA_BETA: u8 = WH_ALPHA | WH_BETA;
